mapper.select:
-- Resolve the immutable content version after idempotent insertion.
SELECT
    ascv.id
FROM announcement_source_content_versions ascv
WHERE ascv.source_id = #{sourceId}
  AND ascv.raw_hash = #{rawHash}

mapper.delete:
-- Replace administrator-confirmed target categories.
DELETE FROM announcement_source_confirmed_target_categories
WHERE source_id = #{sourceId}

-- Replace administrator-confirmed support types.
DELETE FROM announcement_source_confirmed_support_types
WHERE source_id = #{sourceId}
